class PaymentGateway:
    def charge(self, amount):
        raise NotImplementedError

class BasicPaymentGateway(PaymentGateway):
    def process(self, order):
        amount = self.get_amount(order)
        self.charge(amount)
        self.verify_amount(amount, order)
        self.authorize_amount(amount, order)
        self.capture_amount(amount, order)

class AdvancedPaymentGateway(PaymentGateway):
    def process(self, order):
        if order.total > 10000:
            self.basic_gateway.process(order)
        else:
            self.charge(order.total)
            self.verify_amount(order.total, order)
            self.authorize_amount(order.total, order)
            self.capture_amount(order.total, order)

class PayPalGateway(BasicPaymentGateway):
    def get_amount(self, order):
        return order.total

class StripeGateway(AdvancedPaymentGateway):
    def get_amount(self, order):
        return order.total
